  %three = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
  %three_bcast = "stablehlo.broadcast_in_dim"(%three) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %x_plus_3 = "stablehlo.add"(%conv_bias, %three_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Compute relu6(x + 3) = clamp(0, x+3, 6)
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %relu6 = "stablehlo.clamp"(%zero_bcast, %x_plus_3, %six_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Multiply x * relu6(x + 3)
  %hardswish_num = "stablehlo.multiply"(%conv_bias, %relu6) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  // Divide by 6
  %hardswish = "stablehlo.divide"(%hardswish_num, %six_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  // ReLU: maximum(hardswish, 0)
  %relu = "stablehlo.maximum"(%hardswish, %zero_bcast) : (tensor<6x7x4x4xf32>, tensor<6x7x4x4xf32>) -> tensor<6x7x4x4xf32>

  "func.return"(%relu) : (tensor<6x7x4x4xf32>) -> ()
}

func.func @main(
