    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<1x1x1x1xf32>) -> tensor<1x1x1x1x1xf32>
  // Actually simpler to just broadcast 3.0 directly to conv shape
  %three_bcast_full = "stablehlo.broadcast_in_dim"(%three) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>

  %x_plus_3 = "stablehlo.add"(%conv_plus_bias, %three_bcast_full) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>

