    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>
  %six = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x16x13x4x4xf32>

  %relu6 = "stablehlo.clamp"(%zero_bcast, %x_plus_3, %six_bcast) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>

  // x * relu6(x + 3) / 6
  %x_mul_relu6 = "stablehlo.multiply"(%conv_plus_bias, %relu6) : (tensor<6x16x13x4x4xf32>, tensor<6x16x13x4x4xf32>) -> tensor<6x16x13x4x4xf32>
  %six_bcast_for_div = %six_bcast
