  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x4xf32>

  %mean_div = "stablehlo.divide"(%mean, %divisor_bcast) : (tensor<6x4xf32>, tensor<6x4xf32>) -> tensor<6x4xf32>

  // Broadcast mean to input shape
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {
    broadcast_dimensions = dense<[0,1]> : tensor<2xi64>
  } : (tensor<6x4xf32>) -> tensor<6x4x4x13x4x4xf32>

  // Compute variance
  %diff = "stablehlo.subtract"(%hardswish_reshaped, %mean_bcast) : (tensor<6x4x4x13x4x4xf32>, tensor<6x4x4x13x4x4xf32

