func.func @main(
  %multiplier: tensor<16x1x1x1xf32>,
  %conv_weight: tensor<16x3x3x3x3xf32>,
  %conv_bias: tensor<16xf32>,
  %input: tensor<6x3x16x7x7xf32>
) -> tensor<6x14x5x5xf32> {
  // %conv_out = conv3d(input, conv_weight) + conv_bias
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = dense<[1, 1, 1]> : tensor<3xi64>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = dense<[1, 1, 1]> : tensor<3xi64>,
    rhs_dilation = dense<[1, 1, 1]> : tensor<3xi64>,
    window_reversal = dense<[false, false, false]> : tensor<3xi1>,
    dimension_numbers = #stablehlo.conv<[b, 1, 2, 3, f]x[0, 1, 2, 3, i]->[b, 1, 2, 3, f]>,
    batch_group_count = 1 : i64,
    feature_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x14x5x5xf32>

  // Broadcast conv_bias to conv output shape for addition
  %bias_bcast = "stablehlo.broadcast_in_dim"(%conv_bias) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<1x16x1x1xf32>

  // Reshape bias_bcast to match conv output shape (6x16x14x5x5)
  %bias_reshaped = "stablehlo.broadcast_in_dim"(%bias_bcast) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<1x16x1x1xf32>) -> tensor<6x16x14x5x5xf32>

  // Add bias
  %conv_bias_added = "stablehlo.add"(%conv, %bias_reshaped) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Multiply by multiplier (broadcast multiplier from 16x1x1x1 to 6x16x14x5x5)
  %mult_bcast = "stablehlo.broadcast_in_dim"(%multiplier) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16x1x1x1xf32>) -> tensor<1x16x1x1xf32>

  // Reshape multiplier broadcast to 6x16x14x5x5
  %mult_reshaped = "stablehlo.broadcast_in_dim"(%mult_bcast) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<1x16x1x1xf32>) -> tensor<6x16x14x5x5xf32>

  %multiplied1 = "stablehlo.multiply"(%conv_bias_added, %mult_reshaped) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // InstanceNorm3d: compute mean and variance over spatial dims (2,3,4)
  // Compute mean over dims 2,3,4
  %mean = "stablehlo.reduce"(%multiplied1, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[2, 3, 4]> : tensor<3xi64>
  } : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>

  // Compute number of elements per feature: 14*5*5=350
  %num_elements = "stablehlo.constant"() {value = dense<350> : tensor<i64>} : () -> tensor<i64>
  %num_elements_f32 = "stablehlo.convert"(%num_elements) : (tensor<i64>) -> tensor<f32>

  // Broadcast num_elements_f32 to mean shape for division
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements_f32) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<>

  // Divide sum by num_elements to get mean
  %mean_f = "stablehlo.divide"(%mean, %num_elements_bcast) : (tensor<6x16xf32>, tensor<f32>) -> tensor<6x16xf32>

  // Broadcast mean to input shape for variance calculation
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_f) {
    broadcast_dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<6x16xf32>) -> tensor<6x16x14x5x5xf32>

  // Compute (x - mean)
  %centered = "stablehlo.subtract"(%multiplied1, %mean_bcast) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Compute squared centered
  %centered_sq = "stablehlo.multiply"(%centered, %centered) : (tensor<6x16x14x5x5xf32>, tensor<6x16x14x5x5xf32>) -> tensor<6x16x14x5x5xf32>

  // Compute variance sum over dims 2,3,4
  %var_sum = "stablehlo.reduce"(%centered_sq, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[2, 3, 4]> : tensor<3xi64>
  } : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>

  // Compute variance by dividing by num_elements
  %variance = "stablehlo.divide"(%var_sum, %num_elements_bcast) : (tensor<6x16xf32>, tensor<f32>) -> tensor<6x16xf32>

  // epsilon constant 1e-5 for numerical stability
  %epsilon = "stablehlo.constant"() {value = dense<0.00001> : tensor<f32>} : () -> tensor<f32>

  // Broadcast epsilon to variance shape
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<f32>

  // Add epsilon to variance
  %variance_eps = "stablehlo.add"(%variance, %epsilon_bcast) : (tensor<6x16xf32>, tensor<f32>) -> tensor<6x16xf32>

  // Compute rsqrt of variance_eps
  %rsqrt_var = "stablehlo.rsqrt"(%variance_eps) : (tensor<6x16xf32>) -> tensor<6x16xf32>

  // Broadcast scale (multiplier) to input shape for normalization
  %scale_bcast = "stablehlo.broadcast_in_dim"(%multiplier) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16x1x1x1xf32>) -> tensor<1x16x1x1xf32>

  // Broadcast scale to input shape (6x16x14x5x5)
  %scale_reshaped = "stablehlo.broadcast_in_dim"(%scale_bcast) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<1x16x1x1xf32>) -> tensor<6x16x

func.func @main(
  %arg0: tensor<16xf32>,           // bias
  %arg1: tensor<16x16xf32>,        // matmul.weight
  %arg2: tensor<16xf32>,           // matmul.bias
  %arg3: tensor<16xf32>,           // group_norm.weight
  %arg4: tensor<16xf32>,           // group_norm.bias
  %arg5: tensor<16x16xf32>         // input to matmul
) -> tensor<16x16xf32> {
  // %0 = dot_general(%arg5, %arg1) with contracting dims [1] and [0], batching dims [0] and [1]
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [1],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // %1 = add(%0, %arg2)  // add matmul.bias
  %1 = "stablehlo.add"(%0, %arg2) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>

  // Swish activation: x * sigmoid(x)
  // Compute sigmoid(x) = 1 / (1 + exp(-x))
  %neg = "stablehlo.negate"(%1) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %exp_neg = "stablehlo.exponential"(%neg) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %one = "stablehlo.constant"() { value = dense<1.0> : tensor<f32> } : () -> tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {
    broadcast_dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<f32>) -> tensor<16x16xf32>
  %add_exp = "stablehlo.add"(%one_bcast, %exp_neg) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %sigmoid = "stablehlo.divide"(%one_bcast, %add_exp) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %swish = "stablehlo.multiply"(%1, %sigmoid) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias %arg0 (shape [16]) to swish output (shape [16x16])
  // Broadcast bias to shape [16x16] along dimension 1 (features)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %add_bias = "stablehlo.add"(%swish, %bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // GroupNorm with num_groups=16, so each group has 1 channel (feature)
  // feature_index = 1 (features dimension)
  // Compute mean over all dims except feature dim (dim 1)
  // dims to reduce: [0] (batch dimension)
  %dims_to_reduce = "stablehlo.constant"() { value = dense<[0]> : tensor<1xi64> } : () -> tensor<1xi64>
  %mean = "stablehlo.reduce"(%add_bias, "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) ({
    ^bb0(%x: tensor<f32>, %y: tensor<f32>):
      %sum = "stablehlo.add"(%x, %y) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0]> : tensor<1xi64>
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute divisor = size along reduced dims = batch size = 16
  %divisor = "stablehlo.constant"() { value = dense<16.0> : tensor<f32> } : () -> tensor<f32>
  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<f32>

  // mean = sum / divisor
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %mean_div = "stablehlo.divide"(%add_bias, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Actually compute variance:
  // variance = reduce(sum((x - mean)^2)) / divisor
  %sub = "stablehlo.subtract"(%add_bias, %mean_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %sub_sq = "stablehlo.multiply"(%sub, %sub) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %variance_sum = "stablehlo.reduce"(%sub_sq, "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) ({
    ^bb0(%x: tensor<f32>, %y: tensor<f32>):
      %sum = "stablehlo.add"(%x, %y) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0]> : tensor<1xi64>
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  %variance = "stablehlo.divide"(%variance_sum, %divisor) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  %variance_bcast = "stablehlo.broadcast_in_dim"(%variance) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>

  // epsilon constant for numerical stability
  %epsilon = "stablehlo.constant"() { value = dense<1e-5> : tensor<f32> } : () -> tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<f32>

  // stddev = sqrt(variance + epsilon)
  %var_eps = "stablehlo.add"(%variance_bcast, %epsilon_bcast) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  %stddev = "stablehlo.sqrt"(%var_eps) : (tensor<16x16xf32>) -> tensor<16x16xf32>

  // Normalize: (x - mean) / stddev
  %norm = "stablehlo.divide"(%sub, %stddev) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Apply group_norm.weight (%arg3) and group_norm.bias (%arg4)
  // Broadcast weight and bias to shape [16x16] along dimension 1
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_bcast = "stablehlo.broadcast_in_dim"(%arg4) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
