func.func @main(
  %arg0: tensor<7x8x3x3xf32>,   // conv.weight
  %arg1: tensor<7xf32>,         // conv.bias
  %arg2: tensor<6x8x8x8xf32>    // input
) -> tensor<6xf32> {
  // Perform convolution:
  // conv.weight shape: [out_channels=7, in_channels=8, kernel_h=3, kernel_w=3]
  // input shape: [batch=6, in_channels=8, height=8, width=8]
  // PyTorch Conv2d default stride=1, padding=0, dilation=1, groups=1
  // Output shape: [6, 7, 6, 6] because output spatial dims = (8 - 3 + 1) = 6

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = dense<[1, 1]> : tensor<2xi64>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    window_reversal = dense<[false, false]> : tensor<2xi1>,
    dimension_numbers = #stablehlo.conv<[0, 2, 3, 1]x[0, 1, 2, 3]->[0, 2, 3, 1]>,
    batch_group_count = 1 : i64,
    feature_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from shape [7] to [6,7,6,6]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>

  // Broadcast bias to conv output shape [6x7x6x6]
  %bias_bcast_full = "stablehlo.broadcast_in_dim"(%bias_bcast) {
    broadcast_dimensions = dense<[0, 1, 2, 3]> : tensor<4xi64>
  } : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>

  %conv_bias = "stablehlo.add"(%conv, %bias_bcast_full) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Average Pooling with kernel size 4 (default stride = kernel size)
  // PyTorch AvgPool2d with kernel_size=4, stride=4, no padding
  // Input shape: [6,7,6,6]
  // Output shape: floor((6 - 4)/4 + 1) = floor(0.5 + 1) = 1.5 -> 1 (integer floor)
  // So output shape: [6,7,1,1]

  // Use reduce_window with sum and then divide by kernel area (16)
  // Create init value 0.0 for reduce_window
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>

  // Define sum function for reduce_window body
  %sum_body = {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }

  %avg_pool_sum = "stablehlo.reduce_window"(%conv_bias, %zero) %sum_body {
    window_dimensions = dense<[1, 1, 4, 4]> : tensor<4xi64>,
    window_strides = dense<[1, 1, 4, 4]> : tensor<4xi64>,
    base_dilations = dense<[1, 1, 1, 1]> : tensor<4xi64>,
    window_dilations = dense<[1, 1, 1, 1]> : tensor<4xi64>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x7x1x1xf32>

  // Divide by kernel area 16 to get average
  %kernel_area = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
  // Broadcast kernel_area to shape [6x7x1x1]
  %kernel_area_bcast = "stablehlo.broadcast_in_dim"(%kernel_area) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7x1x1xf32>

  %avg_pool = "stablehlo.divide"(%avg_pool_sum, %kernel_area_bcast) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_avg_pool = "stablehlo.negate"(%avg_pool) : (tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
  %exp_neg = "stablehlo.exponential"(%neg_avg_pool) : (tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
  %one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7x1x1xf32>
  %denominator = "stablehlo.add"(%one_bcast, %exp_neg) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>
  %sigmoid = "stablehlo.divide"(%one_bcast, %denominator) : (tensor<6x7x1x1xf32>, tensor<6x7x1x1xf32>) -> tensor<6x7x1x1xf32>

  // Sum over dimensions [1,2,3] (channels and spatial dims)
  // Current shape: [6,7,1,1]
  // Sum over dims 1,2,3 -> result shape [6]

  // Define sum function for reduce
  %reduce_sum_body = {
    ^bb0(%x: tensor<f32>, %y: tensor<f32>):
      %sum = "stablehlo.add"(%x, %y) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }

  // First reduce over dim 1 (channels)
  %reduce_dim1 = "stablehlo.reduce"(%sigmoid, %zero) %reduce_sum_body {
    dimensions = dense<[1]>
  } : (tensor<6x7x1x1xf32>, tensor<f32>) -> tensor<6x1x1x1xf32>

  // Then reduce over dim 2 (height)
  %reduce_dim2 = "stablehlo.reduce"(%reduce_dim1, %zero) %reduce_sum_body {
    dimensions = dense<[2]>
  } : (tensor<6x1x1x1xf32>, tensor<f32>) -> tensor<6x1x1xf32>

  // Then reduce over dim 3 (width)
  %reduce_dim3 = "stablehlo.reduce"(%reduce_dim2, %zero) %reduce_sum_body {
    dimensions = dense<[3]>
  } : (tensor<6x1x1xf32>, tensor<f32>) -> tensor<6xf32>

  "func.return"(%reduce_dim3) : (tensor<6xf32>) -> ()
}

func.func @main(
  %arg0: tensor<7x6x3x3xf32>,   // conv.weight
  %arg1: tensor<7xf32>,         // conv.bias
  %arg2: tensor<6x6x8x8xf32>    // input
) -> tensor<6x7x6x6xf32> {
  // Convolution dimension numbers for PyTorch Conv2d:
  // input: NCHW = [batch=0, channel=1, height=2, width=3]
  // weight: OIHW = [out_channels=0, in_channels=1, kernel_h=2, kernel_w=3]
  // output: NCHW = [batch=0, channel=1, height=2, width=3]
  //
  // StableHLO convolution dimension_numbers attribute:
  //   lhs (input) dims: [N, C, H, W]
  //   rhs (kernel) dims: [O, I, KH, KW]
  //   output dims: [N, O, OH, OW]
  //
  // So dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>
  //
  // But the output shape is tensor<6x7x6x6xf32>, which is N=6, O=7, OH=6, OW=6
  // So output spatial dims are 2 and 3.
  //
  // The input shape is tensor<6x6x8x8xf32>, weight shape is tensor<7x6x3x3xf32>
  //
  // Use default strides=1, padding=0, dilation=1, groups=1

  %0 = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = dense<[1, 1]> : tensor<2xi64>,
    padding = dense<[0, 0, 0, 0]> : tensor<2x2xi64>,
    lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    window_reversal = dense<[false, false]> : tensor<2xi1>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
    batch_group_count = 1 : i64,
    feature_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias %arg1 (shape 7) to output shape (6x7x6x6)
  // broadcast_in_dim with broadcast_dimensions = [1]
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>

  // Broadcast %1 to output shape (6x7x6x6)
  // broadcast_dimensions = [0,1,2,3]
  %2 = "stablehlo.broadcast_in_dim"(%1) {
    broadcast_dimensions = dense<[0, 1, 2, 3]> : tensor<4xi64>
  } : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>

  // Add bias to convolution output
  %3 = "stablehlo.add"(%0, %2) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Apply Mish activation twice: mish(x) = x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))

  // First Mish:
  // softplus = log_plus_one(exp(%3))
