  // matmul.weight shape: [7,7], input shape: [6,7]
  // We want to do: output = input @ weight^T + bias
  // So transpose weight to [7,7] (same shape), but we must specify contracting dims accordingly.
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
