  %2, %3, %4 = "stablehlo.batch_norm_training"(%1, %arg3, %arg4) {
    epsilon = 0.00001 : f32,
    feature_index = 1 : i64
  } : (tensor<6x7xf32>, tensor<7xf32>, tensor<7xf32>) -> (tensor<6x7xf32>, tensor<7xf32>, tensor<7xf32>)

