  %neg_x = "stablehlo.negate"(%7) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  %exp_neg_x = "stablehlo.exponential"(%neg_x) : (tensor<6x7xf32>) -> tensor<6x7xf32>
