  %result = "stablehlo.multiply"(%7, %sigmoid) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  "func.return"(%result) : (tensor<6x7xf32>) -> ()
}

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<6x6xf32> {
  // Create a 6x6 lower triangular mask with 1.0 in lower triangle and 0.0 elsewhere.
  // We create a 2D iota for row and column indices.
  %c6 = stablehlo.constant dense<6> : tensor<i64>
  %c0 = stablehlo.constant dense<0> : tensor<i64>

  // Create row indices: shape (6,6), each row is [0,1,2,3,4,5]
  %iota_dim1 = stablehlo.iota() {iota_dimension = 1 : i64} : () -> tensor<6x6xi64>
  // Create column indices: shape (6,6), each column is [0,1,2,3,4,5]^T
  %iota_dim0 = stablehlo.iota() {iota_dimension = 0 : i64} : () -> tensor<6x6xi64>

  // Compare row indices >= column indices to get lower triangular mask (i1 tensor)
  %mask_bool = stablehlo.compare(%iota_dim0, %iota_dim1) {
    comparison_direction = #stablehlo<comparison_direction GE>,
    compare_type = #stablehlo<comparison_type SIGNED>
  } : (tensor<6x6xi64>, tensor<6x6xi64>) -> tensor<6x6xi1>

  // Convert mask to f32: true -> 1.0, false -> 0.0
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mask = stablehlo.select(%mask_bool, %one, %zero) : (tensor<6x6xi1>, tensor<f32>, tensor<f32>) -> tensor<6x6xf32>

  // Compute dot_general of %arg0 and %arg1 with contracting dims [1] and [0]
  %dot = stablehlo.dot_general(%arg0, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Multiply dot result by mask to zero out upper triangle
  %result = stablehlo.multiply %dot, %mask : tensor<6x6xf32>

  stablehlo.return %result : tensor<6x6xf32>
}

