func.func @main(%arg0: tensor<6x7x5xf32>, %arg1: tensor<6x6x8xf32>) -> tensor<6x7x20xf32> {
  // %arg0: conv1d_transpose.weight, shape [6,7,5]
  // %arg1: input tensor, shape [6,6,8]

  // We want to perform ConvTranspose1d with:
  // in_channels=6, out_channels=7, kernel_size=5, stride=1, padding=0, dilation=3, bias=False
  // The weight shape in PyTorch ConvTranspose1d is (in_channels, out_channels, kernel_size)
  // StableHLO convolution expects weight shape (kernel_spatial_dims..., input_feature_dim, output_feature_dim)
  // So we need to transpose %arg0 from [6,7,5] to [5,6,7]

  // Transpose weight from [6,7,5] to [5,6,7]
  %weight_transposed = "stablehlo.transpose"(%arg0) {
    permutation = dense<[2, 0, 1]> : tensor<3xi64>
  } : (tensor<6x7x5xf32>) -> tensor<5x6x7xf32>

