  %weight_reversed = "stablehlo.reverse"(%weight_transposed) {
    dimensions = dense<[0]> : tensor<1xi64>
  } : (tensor<5x6x7xf32>) -> tensor<5x6x7xf32>

  // Prepare convolution parameters
  // window_strides = [1] (stride=1)
  %window_strides = "stablehlo.constant"() {value = dense<[1]> : tensor<1xi64>} : () -> tensor<1xi64>

