  %lhs_dilation = "stablehlo.constant"() {value = dense<[1]> : tensor<1xi64>} : () -> tensor<1xi64>

  // rhs_dilation = [3] (dilation=3 on kernel)
  %rhs_dilation = "stablehlo.constant"() {value = dense<[3]> : tensor<1xi64>} : () -> tensor<1xi64>

  // window_reversal = [false]
  %window_reversal = "stablehlo.constant"() {value = dense<[false]> : tensor<1xi1>} : () -> tensor<1xi1>

  // dimension_numbers = [b, 0, i, o] x [0, i, o] -> [b, 0, f]
  // For 3D tensors: batch dim=0, spatial dim=1, feature dim=2
  // Input: %arg1 shape [6,6,8] => batch=0, feature=1, spatial=2 in PyTorch
  // But PyTorch input is (N, C_in, L), so batch=0, channel=1, length=2
  // StableHLO convolution dimension_numbers:
  // input_batch_dimension = 0
  // input_feature_dimension = 1
  // input_spatial_dimensions = [2]
  // kernel_input_feature_dimension = 1
  // kernel_output_feature_dimension = 2
  // kernel_spatial_dimensions = [0]
  // output_batch_dimension = 0
  // output_feature_dimension = 2
  // output_spatial_dimensions = [1]

