  // output shape [6x7x20] (batch=0, feature=2, spatial=1)

  // So dimension_numbers = #stablehlo.conv<[b, 2, 1]x[0, 1, 2]->[b, 1, 2]>
  // which is:
  // input_batch_dimension = 0
  // input_feature_dimension = 1
  // input_spatial_dimensions = [2]
  // kernel_input_feature_dimension = 1
  // kernel_output_feature_dimension = 2
  // kernel_spatial_dimensions = [0]
  // output_batch_dimension = 0
  // output_feature_dimension = 2
  // output_spatial_dimensions = [1]

  %result = "stablehlo.convolution"(%arg1, %weight_reversed) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    window_reversal = %window_reversal,
    dimension_numbers = #stablehlo.conv<
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2],
      kernel_input_feature_dimension = 1,
      kernel_output_feature_dimension = 2,
      kernel_spatial_dimensions = [0],
      output_batch_dimension = 0,
      output_feature_dimension = 2,
      output_spatial_dimensions = [1]
    >,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x6x8xf32>, tensor<5x6x7xf32>) -> tensor<6x7x20xf32>

  "func.return"(%result) : (tensor<6x7x20xf32>) -> ()
}

