  // Compute sqrt(2)
  %c_sqrt2 = "stablehlo.constant"() {value = dense<1.4142135623730951> : tensor<f32>} : () -> tensor<f32>
  // Broadcast sqrt(2) scalar to 6x7
  %11 = "stablehlo.broadcast_in_dim"(%c_sqrt2) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7xf32>
  // Divide x by sqrt(2)
  %12 = "stablehlo.divide"(%10, %11) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Compute erf(x / sqrt(2))
  %13 = "stablehlo.erf"(%12) : (tensor<6x7xf32>) -> tensor<6x7xf32>
  // Create constant 0.5 scalar
