  %14 = "stablehlo.broadcast_in_dim"(%c_half) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7xf32>
  // Create constant 1.0 scalar (reuse %6)
  // Add 1 + erf(...)
  %15 = "stablehlo.add"(%6, %13) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>
  // Multiply 0.5 * (1 + erf(...))
