  // Multiply x * above
  %17 = "stablehlo.multiply"(%10, %16) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // Apply Hardtanh with min_val = -1, max_val = 1
  // Create constant -1.0 scalar
  %c_neg1 = "stablehlo.constant"() {value = dense<-1.0> : tensor<f32>} : () -> tensor<f32>
