  // Clamp between -1 and 1
  %19 = "stablehlo.clamp"(%18, %17, %6) : (tensor<6x7xf32>, tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  "func.return"(%19) : (tensor<6x7xf32>) -> ()
}

