func.func @main(%arg0: tensor<16x12x16xf32>) -> tensor<16x12x3xf32> {
  // MaxPool1d parameters:
  // kernel_size = 8
  // stride = 1
  // padding = 4
  // dilation = 3
  // input shape: [16, 12, 16]
  // output length = floor((16 + 2*4 - 3*(8-1) - 1)/1 + 1) = floor((16 + 8 - 21 - 1) + 1) = floor(2) = 2
  // But PyTorch MaxPool1d with dilation=3 and kernel=8 and padding=4 and stride=1 gives output length 3
  // Let's verify output length formula:
  // output_length = floor((input_length + 2*padding - dilation*(kernel_size-1) -1)/stride + 1)
  // = floor((16 + 8 - 21 -1)/1 +1) = floor(2) = 2
  // But PyTorch returns 3, because it uses ceil_mode=False and padding is applied differently.
  // StableHLO pad op can handle negative padding, so we will pad input accordingly.
  // To get output length 3, we pad input to length 20 (16 + 4 + 4), then sliding window with dilation 3 and kernel 8:
  // window size in input space = dilation*(kernel_size-1)+1 = 3*7+1=22, which is larger than padded input length 24
  // So output length = floor((padded_input_length - window_size)/stride + 1) = floor((24-22)/1 +1) = 3
  // So we pad input with 4 zeros on each side.

  // Step 1: Pad input with edge_padding_low=4, edge_padding_high=4, interior_padding=0
  %c4 = stablehlo.constant dense<4> : tensor<i64>
  %edge_padding_low = stablehlo.constant dense<[4]> : tensor<1xi64>
  %edge_padding_high = stablehlo.constant dense<[4]> : tensor<1xi64>
  %interior_padding = stablehlo.constant dense<[0]> : tensor<1xi64>

  // We need to pad only the last dimension (sequence_length dimension)
  // So edge_padding_low and edge_padding_high are rank 3 tensors with zeros except last dim=4
  // Create edge_padding_low tensor: [0,0,4]
  %zero_i64 = stablehlo.constant dense<0> : tensor<i64>
  %edge_padding_low_3d = stablehlo.concatenate(%zero_i64, %zero_i64, %c4) {dimension = 0 : i64} : (tensor<i64>, tensor<i64>, tensor<i64>) -> tensor<3xi64>
  // But concatenate expects tensors of same rank, so instead create constant tensor directly:
  %edge_padding_low_3d = stablehlo.constant dense<[0, 0, 4]> : tensor<3xi64>
  %edge_padding_high_3d = stablehlo.constant dense<[0, 0, 4]> : tensor<3xi64>
  %interior_padding_3d = stablehlo.constant dense<[0, 0, 0]> : tensor<3xi64>

  // padding_value = 0.0f32 scalar
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>

  %padded = stablehlo.dynamic_pad %arg0, %zero_f32, %edge_padding_low_3d, %edge_padding_high_3d, %interior_padding_3d : (tensor<16x12x16xf32>, tensor<f32>, tensor<3xi64>, tensor<3xi64>, tensor<3xi64>) -> tensor<16x12x24xf32>

  // Step 2: reduce_window with max operation
  // window_dimensions = [1, 1, 8]
  %window_dims = stablehlo.constant dense<[1, 1, 8]> : tensor<3xi64>
  // window_strides = [1, 1, 1]
  %window_strides = stablehlo.constant dense<[1, 1, 1]> : tensor<3xi64>
  // base_dilations = [1, 1, 3]
  %base_dilations = stablehlo.constant dense<[1, 1, 3]> : tensor<3xi64>
  // window_dilations = [1, 1, 1]
  %window_dilations = stablehlo.constant dense<[1, 1, 1]> : tensor<3xi64>
  // padding = [[0,0],[0,0],[0,0]] because we already padded input explicitly
  %padding = stablehlo.constant dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>

  // max operation function for reduce_window
  %max_func = {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }

  %result = stablehlo.reduce_window %padded, %zero_f32 {
    window_dimensions = %window_dims,
    window_strides = %window_strides,
    base_dilations = %base_dilations,
    window_dilations = %window_dilations,
    padding = %padding
  }, %max_func : (tensor<16x12x24xf32>, tensor<f32>) -> tensor<16x12x3xf32>

  func.return %result : tensor<16x12x3xf32>
}

func.func @main(%arg0: tensor<7x7x3xf32>, %arg1: tensor<6x7x8xf32>) -> tensor<6x7x10xf32> {
  // We want to perform a ConvTranspose1d with:
  // weight shape: [in_channels=7, out_channels=7, kernel_size=3]
  // input shape: [batch_size=6, in_channels=7, length=8]
  // output shape: [batch_size=6, out_channels=7, length_out=10]
  //
  // PyTorch ConvTranspose1d parameters:
  // stride=1, padding=0, output_padding=0, groups=1, bias=False
  //
  // StableHLO convolution expects:
  // lhs: input tensor
  // rhs: kernel tensor
  //
  // But ConvTranspose1d is a transposed convolution, which can be implemented
  // as a convolution with appropriate dimension numbers and dilation.
  //
  // We implement ConvTranspose1d as a convolution with:
  // lhs = input tensor (N, C_in, L_in)
  // rhs = weight tensor (C_in, C_out, K)
  // output = (N, C_out, L_out)
  //
  // StableHLO convolution expects:
  // lhs shape: [N, spatial_dims..., C_in]
  // rhs shape: [spatial_dims..., C_in, C_out]
  //
  // So we need to transpose the weight from [C_in, C_out, K] to [K, C_in, C_out]
  // and input from [N, C_in, L_in] to [N, L_in, C_in]
  //
  // Then perform convolution with:
  // window_strides = [1]
  // padding = [[0,0]]
  // lhs_dilation = [1] (for normal conv)
  // rhs_dilation = [1]
  // dimension_numbers = [b, 0, f]x[0, i, o]->[b, 0, f]
  //
  // For ConvTranspose1d, the output length is computed as:
  // L_out = (L_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + output_padding + 1
  // Here stride=1, padding=0, dilation=1, output_padding=0
  // So L_out = (8 - 1)*1 - 0 + 1*(3-1) + 0 + 1 = 7 + 2 + 1 = 10
  //
  // To implement ConvTranspose1d as a convolution, we swap lhs and rhs roles,
  // and use lhs_dilation = stride (here 1), rhs_dilation = 1, and appropriate dimension numbers.
  //
  // So we do:
  // lhs = weight tensor transposed to [K, C_in, C_out] -> [1x3x7x7] reshaped to [1x3x7x7] (we'll reshape to 3x7x7)
  // rhs = input tensor transposed to [N, L_in, C_in] -> [6x8x7]
  //
  // Then convolution with:
  // window_strides = [1]
  // padding = [[0,0]]
  // lhs_dilation = [1]
  // rhs_dilation = [1]
  // dimension_numbers = [b, 0, f]x[0, i, o]->[b, 0, f]
  //
  // The output shape will be [6, 10, 7], then we transpose back to [6, 7, 10].
  //
  // But our weight is [7x7x3], so we need to transpose it to [3x7x7].
  //
  // Steps:
  // 1) transpose weight from [7,7,3] to [3,7,7]
  // 2) transpose input from [6,7,8] to [6,8,7]
  // 3) convolution(lhs=weight_transposed, rhs=input_transposed)
  // 4) transpose output from [6,10,7] to [6,7,10]

  // Transpose weight from [7,7,3] to [3,7,7]
  %weight_transposed = "stablehlo.transpose"(%arg0) {
    permutation = dense<[2, 0, 1]> : tensor<3xi64>
  } : (tensor<7x7x3xf32>) -> tensor<3x7x7xf32>

  // Transpose input from [6,7,8] to [6,8,7]
  %input_transposed = "stablehlo.transpose"(%arg1) {
    permutation = dense<[0, 2, 1]> : tensor<3xi64>
  } : (tensor<6x7x8xf32>) -> tensor<6x8x7xf32>

  // Prepare dimension numbers attribute for convolution
  // dimension_numbers = #stablehlo.conv<[b, 0, f]x[0, i, o]->[b, 0, f]>
  // b=batch, 0=spatial dim, f=feature dim
  // lhs: [batch, spatial, feature] = [3,7,7] but batch=3? Actually lhs is weight_transposed: [3,7,7]
  // But weight_transposed shape is [3,7,7], so batch dimension is 0, spatial dim is 1, feature dim is 2
  // rhs: input_transposed shape is [6,8,7], batch=0, spatial=1, feature=2
  // But convolution expects lhs batch dim, spatial dims, feature dim
  // So we need to reshape weight_transposed to add batch dim 1 for convolution
  // Actually, convolution expects lhs shape: [N, spatial_dims..., C_in]
  // Here lhs is weight_transposed: [3,7,7], which is kernel spatial dim=3, input feature=7, output feature=7
  // But we want lhs to be [N, spatial_dims..., C_in], so we treat kernel spatial dim as batch dim? No.
  // Actually, for convolution, lhs is input, rhs is kernel.
  // For ConvTranspose1d, we swap lhs and rhs.
  //
  // So lhs = input_transposed: [6,8,7]
  // rhs = weight_transposed: [3,7,7]
  //
  // dimension_numbers = #stablehlo.conv<[b, 0, f]x[0, i, o]->[b, 0, f]>
  // lhs_batch_dim=0, lhs_spatial_dims=[1], lhs_feature_dim=2
  // rhs_spatial_dims=[0], rhs_input_feature_dim=1, rhs_output_feature_dim=2
  // output_batch_dim=0, output_spatial_dim=1, output_feature_dim=2
  //
  // lhs_dilation = [1] (stride for ConvTranspose1d)
  // rhs_dilation = [1]
  // window_strides = [1]
  // padding = [[0,0]]

  // Perform convolution
  %conv = "stablehlo.convolution"(%input_transposed, %weight_transposed) {
    window_strides = dense<[1]> : tensor<1xi64>,
    padding = dense<[[0, 0]]> : tensor<1x2xi64>,
    lhs_dilation = dense<[1]> : tensor<1xi64>,
    rhs_dilation = dense<[1]> : tensor<1xi64>,
    window_reversal = dense<[false]> : tensor<1xi1>,
    dimension_numbers = #stablehlo.conv<[b, 0, f]x[0, i, o]->[b, 0, f]>,
    batch_group_count = 1 : i64,
    feature_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x8x7xf32>, tensor<3x7x7xf32>) -> tensor<6x10x7xf32>

  // Transpose output from [6,10,7] to [6,7,10]
  %output = "stablehlo.transpose"(%conv) {
    permutation = dense<[0, 2, 1]> : tensor<3xi64>
  } : (tensor<6x10x7xf32>) -> tensor<6x7x10xf32>

  return %output : tensor<6x7x10xf32>
}

