func.func @main(%arg0: tensor<6x7x8x8xf32>) -> tensor<6x7x8x8xf32> {
  // Compute mean over spatial dims (2,3) for each batch and channel
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c1 = stablehlo.constant dense<1> : tensor<i64>
  %mean = stablehlo.reduce %arg0, %c0 {
    dimensions = dense<[2, 3]> : tensor<2xi64>
  } ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Compute number of elements in spatial dims = 8*8=64 as f32 scalar
  %c64 = stablehlo.constant dense<64> : tensor<f32>

  // Broadcast mean to input shape for subtraction
  %mean_bcast = stablehlo.broadcast_in_dim %mean {
    broadcast_dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<6x7xf32>) -> tensor<6x7x8x8xf32>

  // Subtract mean from input
  %centered = stablehlo.subtract %arg0, %mean_bcast : tensor<6x7x8x8xf32>

  // Square centered values
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x8x8xf32>

  // Compute variance over spatial dims (2,3)
  %var = stablehlo.reduce %centered_sq, %c0 {
    dimensions = dense<[2, 3]> : tensor<2xi64>
  } ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Divide variance sum by 64 to get mean variance
  %var_mean = stablehlo.divide %var, %c64 : tensor<6x7xf32>

  // Broadcast variance to input shape
  %var_bcast = stablehlo.broadcast_in_dim %var_mean {
    broadcast_dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<6x7xf32>) -> tensor<6x7x8x8xf32>

  // Add epsilon for numerical stability (default PyTorch epsilon=1e-5)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim %eps {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x7x8x8xf32>
  %var_eps = stablehlo.add %var_bcast, %eps_bcast : tensor<6x7x8x8xf32>

  // Compute rsqrt of variance+eps
  %inv_std = stablehlo.rsqrt %var_eps : tensor<6x7x8x8xf32>

  // Multiply centered by inv_std (normalize)
  %normalized = stablehlo.multiply %centered, %inv_std : tensor<6x7x8x8xf32>

  // Return normalized tensor
  stablehlo.return %normalized : tensor<6x7x8x8xf32>
}

