  %diff = "stablehlo.subtract"(%arg0, %arg1) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Compute abs_diff = abs(diff)
  %abs_diff = "stablehlo.abs"(%diff) : (tensor<6x6xf32>) -> tensor<6x6xf32>

  // constant 1.0 for comparison
  %c1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  // broadcast 1.0 to shape 6x6
  %one = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = dense<[ ]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x6xf32>

  // Compare abs_diff < 1.0
  %cond = "stablehlo.compare"(%abs_diff, %one) {
    comparison_direction = #stablehlo<comparison_direction LT>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute square_term = 0.5 * diff^2
  %half = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = dense<[ ]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x6xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>
  %square_term = "stablehlo.multiply"(%half_bcast, %diff_sq) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Compute linear_term = abs_diff - 0.5
  %linear_term = "stablehlo.subtract"(%abs_diff, %half_bcast) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Select between square_term and linear_term based on cond
  %loss_per_element = "stablehlo.select"(%cond, %square_term, %linear_term) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements of loss_per_element
  %init = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %loss_sum = "stablehlo.reduce"(%loss_per_element, %init) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  // Compute mean loss = loss_sum / 36.0
  %c36 = "stablehlo.constant"() {value = dense<36.0> : tensor<f32>} : () -> tensor<f32>
  %mean_loss = "stablehlo.divide"(%loss_sum, %c36) : (tensor<f32>, tensor<f32>) -> tensor<f32>

  "func.return"(%mean_loss) : (tensor<f32>) -> ()
}

