  %result = "stablehlo.convolution"(%arg1, %0) {
    window_strides = dense<[1]> : tensor<1xi64>,
    padding = dense<[[2, 2]]> : tensor<1x2xi64>,
    lhs_dilation = dense<[2]> : tensor<1xi64>,
    rhs_dilation = dense<[2]> : tensor<1xi64>,
    window_reversal = dense<[false]> : tensor<1xi1>,
    dimension_numbers = #stablehlo.conv<[b, 2, 1]x[2, 0, 1]->[b, 2, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<16x6x8xf32>, tensor<6x7x3xf32>) -> tensor<16x7x17xf32>

  "func.return"(%result) : (tensor<16x7x17xf32>) -> ()
}

func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
