  // %arg2: input x (6x7)

  // Perform linear: y = x * W^T + b
  // x shape: [6,7], W shape: [7,7], want x @ W^T = [6,7] @ [7,7]^T = [6,7] @ [7,7] = [6,7]
  // But PyTorch linear weight is (out_features, in_features) = (7,7)
  // So we do dot_general with lhs = %arg2 (6x7), rhs = %arg0 (7x7), contracting dims: lhs dim 1, rhs dim 1 (input_feature_dimension)
  // Actually, PyTorch linear does x @ W^T + b, so rhs is transposed weight
  // We'll do dot_general with rhs batching dims empty, contracting dims lhs=1, rhs=1, lhs_batching_dims empty, rhs_batching_dims empty
  // But rhs is (7x7), so to do x @ W^T, we need to transpose rhs first

  // Transpose rhs to get W^T: from (7x7) to (7x7) swapping dims 0 and 1
  %rhs_t = "stablehlo.transpose"(%arg0) { permutation = dense<[1, 0]> : tensor<2xi64> } : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // Dot general: lhs_batching_dims = [], rhs_batching_dims = [], lhs_contracting_dims = [1], rhs_contracting_dims = [0]
  %dot = "stablehlo.dot_general"(%arg2, %rhs_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias %arg1 (7) to shape (6x7)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<7xf32>) -> tensor<6x7xf32>

  %linear_out = "stablehlo.add"(%dot, %bias_bcast) : (tensor<6x7xf32>, tensor<6x7xf32>) -> tensor<6x7xf32>

  // sum over dim=1 with keepdim=True: result shape (6x1)
  %sum = "stablehlo.reduce"(%linear_out, "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<6x7xf32>, tensor<f32>) -> tensor<6x1xf32>

  // max over dim=1 with keepdim=True: input shape (6x1), max over dim=1 means dim=1 of size 1, so max is identity
  // But to follow the spec, do max reduce over dim=1
  %max = "stablehlo.reduce"(%sum, "stablehlo.constant"() { value = dense<-inf> : tensor<f32> }) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = "stablehlo.maximum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%max_val) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // mean over dim=1 with keepdim=True: input shape (6x1), mean over dim=1 means dim=1 of size 1, so mean is identity
  // But to follow the spec, do mean reduce over dim=1
  %mean = "stablehlo.reduce"(%max, "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // divide by size of dim=1 (which is 1) to get mean
  %dim1_size = "stablehlo.constant"() { value = dense<1> : tensor<i64> } : () -> tensor<i64>
  %dim1_size_f = "stablehlo.convert"(%dim1_size) : (tensor<i64>) -> tensor<f32>
  %mean_div = "stablehlo.divide"(%mean, %dim1_size_f) : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>

  // logsumexp over dim=1 with keepdim=True: input shape (6x1), logsumexp over dim=1 means dim=1 of size 1, so logsumexp is identity
  // But to follow the spec, do logsumexp over dim=1

  // logsumexp(x) = log(sum(exp(x)))
  %exp = "stablehlo.exponential"(%mean_div) : (tensor<6x1xf32>) -> tensor<6x1xf32>
  %sum_exp = "stablehlo.reduce"(%exp, "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>
  %logsumexp = "stablehlo.log"(%sum_exp) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  // second logsumexp over dim=1 with keepdim=True (same shape)
  %exp2 = "stablehlo.exponential"(%logsumexp) : (tensor<6x1xf32>) -> tensor<6x1xf32>
  %sum_exp2 = "stablehlo.reduce"(%exp2, "stablehlo.constant"() { value = dense<0.0> : tensor<f32> }) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<6x1xf32>, tensor<f32>) -> tensor<6x1xf32>
  %logsumexp2 = "stablehlo.log"(%sum_exp2) : (tensor<6x1xf32>) -> tensor<6x1xf32>

  "func.return"(%logsumexp2) : (tensor<6x1xf32>) -> ()
}

func.func @main(
  %arg0: tensor<16xf32>,          // bias
  %arg1: tensor<16x16xf32>,       // gemm.weight
  %arg2: tensor<16xf32>,          // gemm.bias
  %arg3: tensor<16xf32>,          // groupnorm.weight
  %arg4: tensor<16xf32>,          // groupnorm.bias
  %arg5: tensor<16x16xf32>        // input to gemm
) -> tensor<16x16xf32> {
  // %0 = stablehlo.dot_general(%arg5, %arg1) with batch dims [] and contracting dims [1] and [0]
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // %1 = stablehlo.add(%0, %arg2)  // gemm.bias add
  %1 = "stablehlo.add"(%0, %arg2) : (tensor<16x16xf32>, tensor<16xf32>) -> tensor<16x16xf32>

  // %2 = stablehlo.add(%1, %arg0)  // add bias (bias shape is (16,), broadcast to (16x16))
  %2 = "stablehlo.broadcast_in_dim"(%arg0) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>
  %3 = "stablehlo.add"(%1, %2) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Hardtanh: clamp between 0 and 6
  %4 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %5 = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %6 = "stablehlo.broadcast_in_dim"(%4) {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<16x16xf32>
  %7 = "stablehlo.broadcast_in_dim"(%5) {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<16x16xf32>
  %8 = "stablehlo.maximum"(%3, %6) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %9 = "stablehlo.minimum"(%8, %7) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Mish: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  %10 = "stablehlo.exponential"(%9) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %11 = "stablehlo.add"(%10, %4) : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x16xf32>
  %12 = "stablehlo.log_plus_one"(%11) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %13 = "stablehlo.tanh"(%12) : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %14 = "stablehlo.multiply"(%9, %13) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // GroupNorm:
  // Inputs:
  //   %14: input tensor (N=16, C=16)
  //   %arg3: weight (gamma) shape (16,)
  //   %arg4: bias (beta) shape (16,)
  // Parameters:
  //   num_groups = 16
  // So each channel is its own group (group size = 1)
  // Compute mean and variance per group (per channel)
  // feature_index = 1 (channels dimension)
  // Compute mean:
  //   mean = reduce(%14, init=0, dims=[0]) / N
  // Compute variance:
  //   variance = reduce((%14 - mean)^2, init=0, dims=[0]) / N
  // Normalize:
  //   normalized = (%14 - mean) / sqrt(variance + epsilon)
  // Scale and shift:
  //   output = normalized * weight + bias

  // Compute mean over batch dimension (dim 0)
  %15 = "stablehlo.reduce"(%14, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%arg0: tensor<f32>, %arg1: tensor<f32>):
      %0 = "stablehlo.add"(%arg0, %arg1) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%0) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0]> : tensor<1xi64>
  } : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute divisor = batch size = 16
  %16 = "stablehlo.constant"() {value = dense<16> : tensor<i64>} : () -> tensor<i64>
  %17 = "stablehlo.convert"(%16) : (tensor<i64>) -> tensor<f32>
  // Broadcast divisor to shape of mean (16,)
  %18 = "stablehlo.broadcast_in_dim"(%17) {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<16xf32>

  // mean = sum / divisor
  %19 = "stablehlo.divide"(%15, %18) : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>

  // Broadcast mean to shape of input (16x16)
  %20 = "stablehlo.broadcast_in_dim"(%19) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>

  // centered = x - mean
  %21 = "stablehlo.subtract"(%14, %20) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // squared = centered * centered
  %22 = "stablehlo.multiply"(%21, %21) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Compute variance = reduce(squared, init=0, dims=[0]) / divisor
  %23 = "stablehlo.reduce"(%22, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%arg0: tensor<f32>, %arg1: tensor<f32>):
      %0 = "stablehlo.add"(%arg0, %arg1) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%0) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0]> : tensor<1xi64>
