    lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    window_reversal = dense<[false, false]> : tensor<2xi1>,
    dimension_numbers = #stablehlo.conv<[0, 2, 3, 1]x[2, 3, 1, 0]->[0, 2, 3, 1]>,
    batch_group_count = 1 : i64,
    feature_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<8x6x7x7xf32>, tensor<6x6x3x7xf32>) -> tensor<8x6x9x13xf32>

  // Reverse spatial dims of output to match PyTorch output layout
  %2 = "stablehlo.reverse"(%1) {
    dimensions = dense<[2, 3]> : tensor<2xi64>
  } : (tensor<8x6x9x13xf32>) -> tensor<8x6x9x13xf32>

  return %2 : tensor<8x6x9x13xf32>
}

func.func @main(%x: tensor<4x3xf32>) -> tensor<8x7xf32> {
  %cst = stablehlo.constant dense<-1.0> : tensor<f32>
  %result = stablehlo.pad %x, %cst {
    edge_padding_low = dense<[2, 2]> : tensor<2xi64>,
    edge_padding_high = dense<[2, 2]> : tensor<2xi64>,
    interior_padding = dense<[0, 0]> : tensor<2xi64>
  } : (tensor<4x3xf32>, tensor<f32>) -> tensor<8x7xf32>
  return %result : tensor<8x7xf32>
}

func.func @main(
  %arg0: tensor<6x7x3x3xf32>, 
  %arg1: tensor<7xf32>, 
  %arg2: tensor<16x6x7x7xf32>
) -> tensor<16x7x1x1xf32> {
  // Transpose input to NCHW -> NHWC for convolution
  %0 = "stablehlo.transpose"(%arg2) {
    permutation = dense<[0, 2, 3, 1]> : tensor<4xi64>
  } : (tensor<16x6x7x7xf32>) -> tensor<16x7x7x6xf32>

  // Transpose weight from (in_channels, out_channels, kH, kW) to (kH, kW, out_channels, in_channels)
  %1 = "stablehlo.transpose"(%arg0) {
    permutation = dense<[2, 3, 1, 0]> : tensor<4xi64>
  } : (tensor<6x7x3x3xf32>) -> tensor<3x3x7x6xf32>

  // Convolution parameters
  %window_strides = "stablehlo.constant"() {value = dense<[2, 2]> : tensor<2xi64>} : () -> tensor<2xi64>
  %padding = "stablehlo.constant"() {value = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>} : () -> tensor<2x2xi64>
  %lhs_dilation = "stablehlo.constant"() {value = dense<[1, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
  %rhs_dilation = "stablehlo.constant"() {value = dense<[1, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
  %window_reversal = "stablehlo.constant"() {value = dense<[false, false]> : tensor<2xi1>} : () -> tensor<2xi1>
  %input_batch_dim = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>
  %input_feature_dim = "stablehlo.constant"() {value = dense<3> : tensor<i64>} : () -> tensor<i64>
  %input_spatial_dims = "stablehlo.constant"() {value = dense<[1, 2]> : tensor<2xi64>} : () -> tensor<2xi64>
  %kernel_input_feature_dim = "stablehlo.constant"() {value = dense<2> : tensor<i64>} : () -> tensor<i64>
  %kernel_output_feature_dim = "stablehlo.constant"() {value = dense<3> : tensor<i64>} : () -> tensor<i64>
  %kernel_spatial_dims = "stablehlo.constant"() {value = dense<[0, 1]> : tensor<2xi64>} : () -> tensor<2xi64>
  %output_batch_dim = "stablehlo.constant"() {value = dense<0> : tensor<i64>} : () -> tensor<i64>
  %output_feature_dim = "stablehlo.constant"() {value = dense<3> : tensor<i64>} : () -> tensor<i64>
  %output_spatial_dims = "stablehlo.constant"() {value = dense<[1, 2]> : tensor<2xi64>} : () -> tensor<2xi64>
  %feature_group_count = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
  %batch_group_count = "stablehlo.constant"() {value = dense<1> : tensor<i64>} : () -> tensor<i64>
  %precision_default = #stablehlo<precision DEFAULT>
  %precision_config = stablehlo.constant dense<[0, 0]> : tensor<2xi32> // dummy placeholder for precision config

  // Dimension numbers attribute for convolution
  %dim_numbers = #stablehlo.conv<[b, 1, 2, f]x[0, 1, i, o]->[b, 1, 2, f]>

  // Perform convolution (transposed convolution is convolution with weight transposed and input/output dims swapped)
  %conv = "stablehlo.convolution"(%0, %1) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    window_reversal = %window_reversal,
    input_batch_dimension = 0 : i64,
    input_feature_dimension = 3 : i64,
    input_spatial_dimensions = dense<[1, 2]> : tensor<2xi64>,
    kernel_input_feature_dimension = 2 : i64,
    kernel_output_feature_dimension = 3 : i64,
    kernel_spatial_dimensions = dense<[0, 1]> : tensor<2xi64>,
    output_batch_dimension = 0 : i64,
    output_feature_dimension = 3 : i64,
    output_spatial_dimensions = dense<[1, 2]> : tensor<2xi64>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>],
    dimension_numbers = %dim_numbers
  } : (tensor<16x7x7x6xf32>, tensor<3x3x7x6xf32>) -> tensor<16x7x15x15xf32>

  // Multiply by multiplier 0.5 (broadcast scalar)
  %multiplier = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %conv_mul = "stablehlo.multiply"(%conv, %multiplier) : (tensor<16x7x15x15xf32>, tensor<f32>) -> tensor<16x7x15x15xf32>

  // First global average pooling over spatial dims [2, 3] (dims 2 and 3)
  // Compute mean over dim 2
  %dim2_size = "stablehlo.get_dimension_size"(%conv_mul) {dimension = 2 : i64} : (tensor<16x7x15x15xf32>) -> tensor<i32>
  %dim2_size_f32 = "stablehlo.convert"(%dim2_size) : (tensor<i32>) -> tensor<f32>
  %sum_dim2 = "stablehlo.reduce"(%conv_mul, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[2]> : tensor<1xi64>
  } : (tensor<16x7x15x15xf32>, tensor<f32>) -> tensor<16x7x1x15xf32>
  %mean_dim2 = "stablehlo.divide"(%sum_dim2, %dim2_size_f32) : (tensor<16x7x1x15xf32>, tensor<f32>) -> tensor<16x7x1x15xf32>

  // Compute mean over dim 3 (now dim 3 is size 15)
  %dim3_size = "stablehlo.get_dimension_size"(%mean_dim2) {dimension = 3 : i64} : (tensor<16x7x1x15xf32>) -> tensor<i32>
  %dim3_size_f32 = "stablehlo.convert"(%dim3_size) : (tensor<i32>) -> tensor<f32>
  %sum_dim3 = "stablehlo.reduce"(%mean_dim2, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[3]> : tensor<1xi64>
  } : (tensor<16x7x1x15xf32>, tensor<f32>) -> tensor<16x7x1x1xf32>
  %mean_dim3 = "stablehlo.divide"(%sum_dim3, %dim3_size_f32) : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x7x1x1xf32>

  // Add bias: broadcast bias %arg1 (7xf32) to shape 16x7x1x1
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<7xf32>) -> tensor<16x7x1x1xf32>

func.func @main(%x: tensor<6x6xf32>) -> tensor<6x6xf32> {
  %iota0 = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<6x6xi32>
  %iota1 = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<6x6xi32>
  %cmp = "stablehlo.compare"(%iota1, %iota0) {
    comparison_direction = #stablehlo<comparison_direction LE>,
    compare_type = #stablehlo<comparison_type SIGNED>
  } : (tensor<6x6xi32>, tensor<6x6xi32>) -> tensor<6x6xi1>
  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {
    broadcast_dimensions = dense<[0, 1]> : tensor<2xi64>
  } : (tensor<f32>) -> tensor<6x6xf32>
  %result = "stablehlo.select"(%cmp, %x, %zero_bcast) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>
  "func.return"(%result) : (tensor<6x6xf32>) -> ()
}

func.func @main(
  %arg0: tensor<16x8x3x3xf32>,   // conv.weight
  %arg1: tensor<16xf32>,         // conv.bias
  %arg2: tensor<16xf32>,         // group_norm.weight (gamma)
  %arg3: tensor<16xf32>,         // group_norm.bias (beta)
  %arg4: tensor<16x8x16x16xf32>  // input
) -> tensor<16x1x14x14xf32> {
  // Convolution:
  // conv2d with stride=1, padding=0 (default), no dilation, no groups (groups=1)
  // dimension_numbers = #stablehlo.conv<[b, h, w, c]x[h, w, i, o]->[b, h, w, c]>
  // But PyTorch conv2d input is NCHW, StableHLO conv expects NHWC by default.
  // So we transpose input and weight accordingly.
  // Input: NCHW -> NHWC
  %input_nhwc = "stablehlo.transpose"(%arg4) {
    permutation = dense<[0, 2, 3, 1]> : tensor<4xi64>
  } : (tensor<16x8x16x16xf32>) -> tensor<16x16x16x8xf32>

  // Weight: OIHW -> HWIO
  %weight_hwio = "stablehlo.transpose"(%arg0) {
    permutation = dense<[2, 3, 1, 0]> : tensor<4xi64>
  } : (tensor<16x8x3x3xf32>) -> tensor<3x3x8x16xf32>

  // Convolution parameters:
  // window_strides = [1,1]
  // padding = [[0,0],[0,0]]
  // lhs_dilation = [1,1]
  // rhs_dilation = [1,1]
  // window_reversal = [false,false]
  // dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>
  // input_batch_dimension=0, input_feature_dimension=3, input_spatial_dimensions=[1,2]
  // kernel_input_feature_dimension=2, kernel_output_feature_dimension=3, kernel_spatial_dimensions=[0,1]
  // output_batch_dimension=0, output_feature_dimension=3, output_spatial_dimensions=[1,2]
  %conv = "stablehlo.convolution"(%input_nhwc, %weight_hwio) {
    window_strides = dense<[1, 1]> : tensor<2xi64>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    rhs_dilation = dense<[1, 1]> : tensor<2xi64>,
    window_reversal = dense<[false, false]> : tensor<2xi1>,
    dimension_numbers = #stablehlo.conv<
      input_batch_dimension = 0,
      input_feature_dimension = 3,
      input_spatial_dimensions = [1, 2],
      kernel_input_feature_dimension = 2,
      kernel_output_feature_dimension = 3,
      kernel_spatial_dimensions = [0, 1],
      output_batch_dimension = 0,
      output_feature_dimension = 3,
      output_spatial_dimensions = [1, 2]
    >,
    batch_group_count = 1 : i64,
    feature_group_count = 1 : i64,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<16x16x16x8xf32>, tensor<3x3x8x16xf32>) -> tensor<16x14x14x16xf32>

  // Add bias: conv output shape is [16,14,14,16], bias shape is [16]
  // Broadcast bias to [16,14,14,16] along feature dimension (3)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = dense<[0]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x1x1x16xf32>

  %bias_bcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_bcast) {
    broadcast_dimensions = dense<[0, 1, 2, 3]> : tensor<4xi64>
  } : (tensor<16x1x1x16xf32>) -> tensor<16x14x14x16xf32>

  %conv_bias = "stablehlo.add"(%conv, %bias_bcast_reshaped) : (tensor<16x14x14x16xf32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>

  // GroupNorm:
  // PyTorch GroupNorm with groups=16, channels=16 means each group has 1 channel.
  // So normalization is per channel (feature dim).
  // Compute mean and variance over axes except feature dim (axis=3)
  // axes to reduce: [0,1,2]
  %axes = "stablehlo.constant"() {value = dense<[0, 1, 2]> : tensor<3xi64>} : () -> tensor<3xi64>

  // Compute mean: reduce sum over axes [0,1,2], then divide by (16*14*14)
  %sum = "stablehlo.reduce"(%conv_bias, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0, 1, 2]> : tensor<3xi64>
  } : (tensor<16x14x14x16xf32>, tensor<f32>) -> tensor<1x1x1x16xf32>

  // divisor = 16*14*14 = 3136.0
  %divisor = "stablehlo.constant"() {value = dense<3136.0> : tensor<f32>} : () -> tensor<f32>
  %divisor_bcast = "stablehlo.broadcast_in_dim"(%divisor) {
    broadcast_dimensions = dense<[]> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<1x1x1x1xf32>

  %mean = "stablehlo.divide"(%sum, %divisor_bcast) : (tensor<1x1x1x16xf32>, tensor<1x1x1x1xf32>) -> tensor<1x1x1x16xf32>

  // Broadcast mean to conv_bias shape for variance computation
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = dense<[0, 1, 2, 3]> : tensor<4xi64>
  } : (tensor<1x1x1x16xf32>) -> tensor<16x14x14x16xf32>

  // centered = conv_bias - mean_bcast
  %centered = "stablehlo.subtract"(%conv_bias, %mean_bcast) : (tensor<16x14x14x16xf32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>

  // squared = centered * centered
  %squared = "stablehlo.multiply"(%centered, %centered) : (tensor<16x14x14x16xf32>, tensor<16x14x14x16xf32>) -> tensor<16x14x14x16xf32>

  // sum of squared over axes [0,1,2]
  %sum_sq = "stablehlo.reduce"(%squared, "stablehlo.constant"() {value = dense<0.0> : tensor<f32>}) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0, 1, 2]> : tensor<3xi64>
  } : (tensor<16x14x14x16xf32>, tensor<f32>) -> tensor<1x1x1x16xf32>

  // variance = sum_sq / divisor
  %variance = "stablehlo.divide"(%sum_sq, %divisor_bcast) : (tensor<1x1x1x16xf32>, tensor<1x1x1x1xf32>) -> tensor<1x1x1x16xf32>

  // Broadcast variance to conv_bias shape
  %variance_bcast = "stablehlo.broadcast_in_dim"

func.func @main(
  %arg0: tensor<1x16x1x1xf32>,       // bias
  %arg1: tensor<16x16xf32>,          // gemm.weight
  %arg2: tensor<16xf32>,             // gemm.bias
  %arg3: tensor<16xf32>,             // group_norm.weight
  %arg4: tensor<16xf32>,             // group_norm.bias
  %arg5: tensor<16x16xf32>           // input to forward (x)
) -> tensor<1x16x16x1xf32> {
  // Step 1: GEMM: x @ weight^T + bias
  // %arg5 shape: [16,16]
  // %arg1 shape: [16,16] (weight)
  // We want to do dot_general with lhs = %arg5, rhs = %arg1 transposed
  // But gemm.weight is [16x16], so we transpose it to [16x16] (same shape)
  // We'll do dot_general with contracting dims [1] for lhs and [1] for rhs (rhs is transposed)
  // Actually, gemm.weight is [16x16], so we transpose it to [16x16] swapping dims 0 and 1
  // Then dot_general(lhs=%arg5, rhs=weight_T) with contracting dims [1] and [0]
  // Result shape: [16,16]

  %weight_t = "stablehlo.transpose"(%arg1) {
    permutation = dense<[1, 0]> : tensor<2xi64>
  } : (tensor<16x16xf32>) -> tensor<16x16xf32>

  %gemm_dot = "stablehlo.dot_general"(%arg5, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >,
    precision_config = [#stablehlo<precision DEFAULT>, #stablehlo<precision DEFAULT>]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add gemm.bias (%arg2) to gemm_dot result
  // gemm.bias shape: [16]
  // gemm_dot shape: [16,16]
  // Broadcast gemm.bias to [16,16] along dimension 1
  %gemm_bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<16x16xf32>

  %gemm_out = "stablehlo.add"(%gemm_dot, %gemm_bias_bcast) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: GroupNorm
  // GroupNorm with num_groups=16, out_features=16
  // Input shape: [16,16]
  // We need to reshape to [1,16,16,1] to match expected 4D input for group norm
  %gemm_out_reshaped = "stablehlo.reshape"(%gemm_out) : (tensor<16x16xf32>) -> tensor<1x16x16x1xf32>

  // Compute mean and variance over group norm axes
  // GroupNorm normalizes over all dims except channel dim (1)
  // So reduce over dims [0,2,3]

  // Compute mean
  %zero_f32 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_out_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0, 2, 3]> : tensor<3xi64>
  } : (tensor<1x16x16x1xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute divisor = product of reduced dims sizes = 1*16*1=16
  %const_16 = "stablehlo.constant"() {value = dense<16> : tensor<i64>} : () -> tensor<i64>
  %const_16_f32 = "stablehlo.convert"(%const_16) : (tensor<i64>) -> tensor<f32>

  // Broadcast divisor to mean shape (16)
  // mean shape is [16], so no broadcast needed

  // Compute mean / divisor
  %mean_div = "stablehlo.divide"(%mean, %const_16_f32) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // Broadcast mean to input shape for variance calculation
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<1x16x16x1xf32>

  // Compute (x - mean)^2
  %diff = "stablehlo.subtract"(%gemm_out_reshaped, %mean_bcast) : (tensor<1x16x16x1xf32>, tensor<1x16x16x1xf32>) -> tensor<1x16x16x1xf32>
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<1x16x16x1xf32>, tensor<1x16x16x1xf32>) -> tensor<1x16x16x1xf32>

  // Compute variance sum
  %var_sum = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {
    dimensions = dense<[0, 2, 3]> : tensor<3xi64>
  } : (tensor<1x16x16x1xf32>, tensor<f32>) -> tensor<16xf32>

  // Compute variance = var_sum / divisor
  %variance = "stablehlo.divide"(%var_sum, %const_16_f32) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // Add epsilon for numerical stability
  %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<1x16x16x1xf32>

  %variance_bcast = "stablehlo.broadcast_in_dim"(%variance) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<1x16x16x1xf32>

  %variance_eps = "stablehlo.add"(%variance_bcast, %epsilon_bcast) : (tensor<1x16x16x1xf32>, tensor<1x16x16x1xf32>) -> tensor<1x16x16x1xf32>

  // Compute rsqrt(variance + epsilon)
  %inv_stddev = "stablehlo.rsqrt"(%variance_eps) : (tensor<1x16x16x1xf32>) -> tensor<1x16x16x1xf32>

  // Broadcast group_norm.weight (%arg3) and bias (%arg4) to input shape
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<1x16x16x1xf32>

  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg4) {
    broadcast_dimensions = dense<[1]> : tensor<1xi64>
  } : (tensor<16xf32>) -> tensor<1x16x16x1xf32>

  // Normalize: (x - mean) * inv_stddev
  %centered = "stablehlo.subtract"(%gemm_out_reshaped, %mean_bcast) : (tensor<1x16x16x1xf32>, tensor<1x16x16x1xf32>) -> tensor<1x16x16x1xf32>
  %normalized = "stablehlo.multiply"(%centered, %inv_stddev) : (tensor<1x16x16x1xf32>, tensor<1x16x16x1xf32>) -> tensor<1x16x
